/**
 * Files of the local portal (`tunelo http` serves it on 127.0.0.1:4041), by
 * URL path. The release binary embeds them: its entry, generated by
 * `scripts/build-portal.ts`, imports each file with `{ type: "file" }` and
 * hands the paths here before starting the CLI. Run from the sources, the
 * files come from `dist/portal` once `pnpm build:portal` ran.
 */
import { existsSync, readdirSync, statSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

export type PortalAssets = Readonly<Record<string, string>>;

let embedded: PortalAssets | null = null;

/** Called by the generated release entry. */
export function setPortalAssets(assets: PortalAssets): void {
	embedded = assets;
}

/** `dist/portal` beside the sources, as `pnpm build:portal` leaves it. */
export function builtPortalDir(): string {
	return resolve(dirname(fileURLToPath(import.meta.url)), "../../dist/portal");
}

function listFiles(root: string, dir = root): string[] {
	return readdirSync(dir).flatMap((name) => {
		const full = join(dir, name);
		return statSync(full).isDirectory() ? listFiles(root, full) : [full];
	});
}

/** Path → file on disk of every portal file; empty when the portal was not built. */
export function portalAssets(): PortalAssets {
	if (embedded) return embedded;
	const root = builtPortalDir();
	if (!existsSync(root)) return {};
	const assets: Record<string, string> = {};
	for (const file of listFiles(root)) {
		assets[`/${relative(root, file).split(sep).join("/")}`] = file;
	}
	return assets;
}
